import React from "react";
import { AbsoluteFill, Img, OffthreadVideo, Sequence, useCurrentFrame } from "remotion";
import { ANTON, asset, Back, Blade, BG, Clock, Col, ein, GOLD, GOLD_GRAD, GOLD_HI, io, k, lin, Line, mix, MONT, pop, WHITE } from "./comum";
import { End, MD_FPS, S1, S4, S5 } from "./Mendes";

// Mendes Delivery v2 — vitrine com o material do próprio cliente (vídeos e foto), mesma voz da v1.
// Cenas desenhadas da v1 (relógio, comodidade, casa, final) se intercalam com as filmagens.
// Tempos = tempo da voz cortada (src/voz-v1-cortada.wav) + VO.

const VO = 0.25;
const v = (s: number) => s + VO;
export const MD2_FRAMES = Math.round((34.13 + VO + 1.5) * MD_FPS);
const live = (t: number, a: number, b: number) => t > a - 0.05 && t < b + 0.05;
const INK = "#140E04";

// filmagem do cliente em tela cheia, com aproximação lenta e um deslize curto
const Clip: React.FC<{ src: string; at: number; from: number; t: number; z0?: number; z1?: number; dx?: number; pos?: string; len?: number }> = ({ src, at, from, t, z0 = 1.04, z1 = 1.12, dx = 0, pos = "50% 50%", len = 4 }) => {
  const p = lin(t, at, at + len);
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <Sequence from={Math.round(at * MD_FPS)} layout="none">
        <OffthreadVideo src={asset(src)} muted startFrom={Math.round(from * MD_FPS)} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `scale(${mix(z0, z1, p).toFixed(4)}) translateX(${(dx * p).toFixed(1)}px)` }} />
      </Sequence>
    </AbsoluteFill>
  );
};

// degradê leve embaixo, só o bastante para o lettering
const Shade: React.FC<{ s?: number }> = ({ s = 1 }) => (
  <AbsoluteFill style={{ background: `linear-gradient(180deg, rgba(0,0,0,0) 52%, rgba(0,0,0,${(0.5 * s).toFixed(2)}) 70%, rgba(0,0,0,${(0.72 * s).toFixed(2)}) 100%)` }} />
);

// faixa dourada que corre da esquerda e a palavra sobe de dentro dela
const Band: React.FC<{ t: number; at: number; text: string; size: number }> = ({ t, at, text, size }) => {
  const w = io(t, at - 0.1, 0.32);
  const e = k(t, at + 0.05, 0.42);
  return (
    <div style={{ position: "relative", padding: `${size * 0.04}px ${size * 0.22}px ${size * 0.02}px`, margin: `${size * 0.1}px 0` }}>
      <div style={{ position: "absolute", inset: 0, background: GOLD_GRAD, borderRadius: 10, transform: `scaleX(${w.toFixed(3)}) skewX(-8deg)`, transformOrigin: "0 50%", boxShadow: "0 14px 40px rgba(0,0,0,0.45)" }} />
      <div style={{ position: "relative", overflow: "hidden" }}>
        <div style={{ fontFamily: ANTON, fontSize: size, lineHeight: 1.08, color: INK, textTransform: "uppercase", letterSpacing: "0.01em", whiteSpace: "nowrap", transform: `translateY(${((1 - e) * 130).toFixed(1)}%)` }}>{text}</div>
      </div>
    </div>
  );
};

// ───── 2 · "Então por que perder horas lavando o carro?" — Jeep enlameado ─────
const S2: React.FC<{ t: number }> = ({ t }) => {
  const a = v(2.05);
  const e = k(t, a, 0.6);
  return (
    <AbsoluteFill style={{ transform: `scale(${mix(1.25, 1, e).toFixed(4)})`, filter: `blur(${((1 - e) * 14).toFixed(1)}px)`, opacity: Math.min(1, e * 2.5) }}>
      <Clip src="video-2.mp4" at={a - 0.1} from={0.2} t={t} z0={1.06} z1={1.16} dx={-30} len={3} pos="50% 40%" />
      <Shade />
      <Col top={990}>
        <Line t={t} size={84} words={[["então", v(2.31)], ["por", v(2.36)], ["que", v(2.37)], ["perder", v(2.65)]]} />
        <Band t={t} at={v(3.32)} text="horas" size={170} />
        <Line t={t} size={92} words={[["lavando", v(3.58)], ["o", v(3.98)], ["carro?", v(4.02)]]} />
      </Col>
    </AbsoluteFill>
  );
};

// ───── 3 · "Na Mendes, a gente não vende só limpeza" — Porsche na espuma ─────
const S3: React.FC<{ t: number }> = ({ t }) => {
  const a = v(4.85);
  const strike = io(t, v(7.55), 0.35);
  return (
    <AbsoluteFill>
      <Clip src="video-1.mp4" at={a - 0.3} from={0} t={t} z0={1.1} z1={1.02} pos="50% 45%" len={3.6} />
      <Shade />
      <Col top={1030}>
        <Line t={t} size={60} gold font={MONT} spacing="0.18em" words={[["Na", v(5.11)], ["Mendes,", v(5.15)]]} />
        <div style={{ height: 6 }} />
        <Line t={t} size={104} words={[["a", v(5.72)], ["gente", v(5.75)], ["não", v(6.15)], ["vende", v(6.41)]]} />
        <div style={{ position: "relative" }}>
          <Line t={t} size={170} color={strike > 0 ? `rgba(255,255,255,${(1 - strike * 0.4).toFixed(2)})` : WHITE} words={[["só", v(6.83)], ["limpeza", v(6.98)]]} />
          <div style={{ position: "absolute", left: -20, right: -20, top: "52%", height: 16, borderRadius: 8, background: GOLD_GRAD, transform: `scaleX(${strike}) rotate(-3deg)`, transformOrigin: "0 50%", boxShadow: "0 0 24px rgba(233,185,73,0.5)" }} />
        </div>
      </Col>
    </AbsoluteFill>
  );
};

// ───── 6 · "A gente leva toda a estrutura até você" — o Mendes trabalhando na casa do cliente ─────
const S6: React.FC<{ t: number }> = ({ t }) => {
  const a = v(13.62);
  const up = 1 - k(t, a - 0.02, 0.42); // sobe empurrando a casa
  const whip = ein(t, v(16.55), 0.28);
  return (
    <AbsoluteFill style={{ transform: `translateY(${(up * 1920).toFixed(1)}px) translateX(${(-whip * 1300).toFixed(1)}px)`, filter: `blur(${(whip * 18).toFixed(1)}px)` }}>
      <Clip src="video-1.mp4" at={a - 0.3} from={11.4} t={t} z0={1.02} z1={1.1} dx={20} pos="50% 45%" len={3.3} />
      <Shade />
      <Col top={990}>
        <Line t={t} size={88} words={[["a", v(13.94)], ["gente", v(13.98)], ["leva", v(14.25)], ["toda", v(14.4)]]} />
        <Line t={t} size={128} words={[["a", v(14.7)], ["estrutura", v(14.8)]]} />
        <Band t={t} at={v(15.55)} text="até você" size={140} />
      </Col>
    </AbsoluteFill>
  );
};

// ───── 7 · "Produtos e equipamentos de alto padrão" — espuma no pneu ─────
const S7: React.FC<{ t: number }> = ({ t }) => {
  const a = v(16.65);
  const e = k(t, a, 0.5);
  return (
    <AbsoluteFill style={{ transform: `translateX(${mix(1300, 0, e).toFixed(1)}px)`, filter: `blur(${((1 - e) * 16).toFixed(1)}px)` }}>
      <Clip src="video-3.mp4" at={a - 0.2} from={0.4} t={t} z0={1.12} z1={1.04} pos="50% 40%" len={2.8} />
      <Shade s={1.35} />
      <Col top={1050}>
        <Line t={t} size={84} words={[["produtos", v(17.05)], ["e", v(17.2)]]} />
        <Line t={t} size={120} words={[["equipamentos", v(17.3)]]} />
        <Band t={t} at={v(18.25)} text="de alto padrão" size={108} />
      </Col>
    </AbsoluteFill>
  );
};

// ───── 7b · "num serviço premium" — VW pronto, placa Mendes (foto inteira, larga) ─────
const S7b: React.FC<{ t: number }> = ({ t }) => {
  const a = v(19.0);
  const iris = io(t, a - 0.05, 0.45);
  const out = ein(t, v(20.85), 0.28);
  const z = 1.02 + lin(t, a, v(21)) * 0.07;
  return (
    <AbsoluteFill style={{ clipPath: `circle(${(iris * 120).toFixed(2)}% at 50% 42%)`, transform: `translateX(${(-out * 1300).toFixed(1)}px)`, filter: `blur(${(out * 18).toFixed(1)}px)` }}>
      <Back />
      <div style={{ position: "absolute", left: 0, top: -260, width: 1080, height: 1438, overflow: "hidden" }}>
        <Img src={asset("foto-vw.jpg")} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${z.toFixed(4)})`, transformOrigin: "95% 70%" }} />
        <AbsoluteFill style={{ background: `linear-gradient(180deg, rgba(8,7,6,0) 70%, ${BG} 100%)` }} />
      </div>
      <Col top={1055}>
        <Line t={t} size={110} words={[["num", v(19.1)], ["serviço", v(19.3)]]} />
        <div style={{ position: "relative" }}>
          <Band t={t} at={v(19.85)} text="premium" size={190} />
          {[[-60, 150, 0], [640, -12, 0.1], [630, 185, 0.18]].map(([x, y, d], i) => {
            const s = pop(t, v(19.95) + d, 0.4);
            return (
              <svg key={i} width={70} height={70} viewBox="-10 -10 20 20" style={{ position: "absolute", left: x, top: y, transform: `scale(${(s * (i === 1 ? 1 : 0.7)).toFixed(3)}) rotate(${(t * 40).toFixed(0)}deg)` }}>
                <path d="M0 -10 C1 -2 2 -1 10 0 C2 1 1 2 0 10 C-1 2 -2 1 -10 0 C-2 -1 -1 -2 0 -10 Z" fill={GOLD_HI} />
              </svg>
            );
          })}
        </div>
      </Col>
    </AbsoluteFill>
  );
};

// ───── 8 · "Você continua fazendo as suas coisas" — o relógio volta (fio do vídeo) ─────
const S8: React.FC<{ t: number }> = ({ t }) => {
  const a = v(20.95);
  const e = k(t, a, 0.5);
  return (
    <AbsoluteFill style={{ transform: `translateX(${mix(1300, 0, e).toFixed(1)}px) scale(${(1 + lin(t, a, v(23.6)) * 0.05).toFixed(4)})`, filter: `blur(${((1 - e) * 16).toFixed(1)}px)` }}>
      <Back />
      <div style={{ position: "absolute", left: 0, right: 0, top: 400, display: "flex", justifyContent: "center" }}>
        <Clock t={t} p={k(t, a, 0.7)} speed={(t - a) * 30} size={440} />
      </div>
      <Col top={980}>
        <Line t={t} size={130} words={[["você", v(21.17)], ["continua", v(21.5)]]} />
        <Line t={t} size={96} words={[["fazendo", v(21.63)]]} />
        <Line t={t} size={116} gold words={[["as", v(22.2)], ["suas", v(22.45)], ["coisas", v(22.7)]]} />
      </Col>
    </AbsoluteFill>
  );
};

// ───── 8b · "e a gente cuida do seu carro" — Jeep limpo, sobe por uma cortina com fio dourado ─────
const S8b: React.FC<{ t: number }> = ({ t }) => {
  const a = v(23.4);
  const w = io(t, a - 0.05, 0.5);
  const edge = (1 - w) * 100;
  return (
    <>
      <AbsoluteFill style={{ clipPath: `inset(${edge.toFixed(2)}% 0 0 0)` }}>
        <Clip src="video-4.mp4" at={a - 0.1} from={0.3} t={t} z0={1.14} z1={1.04} dx={-20} pos="50% 45%" len={2.6} />
        <Shade />
        <Col top={1120}>
          <Line t={t} size={110} words={[["e", v(23.62)], ["a", v(23.66)], ["gente", v(23.7)], ["cuida", v(23.92)]]} />
          <Band t={t} at={v(24.4)} text="do seu carro" size={140} />
        </Col>
      </AbsoluteFill>
      {w > 0 && w < 1 ? <div style={{ position: "absolute", left: 0, right: 0, top: `${edge.toFixed(2)}%`, height: 10, marginTop: -5, background: GOLD_GRAD, boxShadow: `0 0 30px ${GOLD}` }} /> : null}
    </>
  );
};

export const MendesV2: React.FC = () => {
  const f = useCurrentFrame();
  const t = f / MD_FPS;
  const flood = io(t, v(8.0), 0.5);
  const back = io(t, v(10.45), 0.45);
  const s5out = t > v(13.6);
  return (
    <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
      <Back />
      {live(t, 0, v(2.4)) ? <S1 t={t} big={180} /> : null}
      {live(t, v(2.0), v(4.95)) ? <S2 t={t} /> : null}
      <Blade t={t} at={v(4.85)} dir={-1} />
      {live(t, v(4.8), v(8.5)) ? <S3 t={t} /> : null}
      {flood > 0 && back < 1 ? (
        <AbsoluteFill style={{ background: GOLD_GRAD, clipPath: `circle(${(flood * 160).toFixed(2)}% at 88% 62%)` }}>
          {t > v(8.2) ? <S4 t={t} big={150} /> : null}
        </AbsoluteFill>
      ) : null}
      {back > 0 && live(t, v(10.4), v(14.1)) ? (
        <AbsoluteFill style={{ clipPath: `circle(${(back * 120).toFixed(2)}% at 50% 50%)` }}>
          <AbsoluteFill style={{ transform: s5out ? `translateY(${(-k(t, v(13.6), 0.42) * 1920).toFixed(1)}px)` : undefined }}>
            <Back />
          </AbsoluteFill>
          {live(t, v(10.5), v(14)) ? <S5 t={t} big={152} /> : null}
        </AbsoluteFill>
      ) : null}
      {live(t, v(13.55), v(16.9)) ? <S6 t={t} /> : null}
      {live(t, v(16.6), v(19.5)) ? <S7 t={t} /> : null}
      {live(t, v(18.95), v(21.2)) ? <S7b t={t} /> : null}
      {live(t, v(20.9), v(24.0)) ? <S8 t={t} /> : null}
      {live(t, v(23.3), v(26.0)) ? <S8b t={t} /> : null}
      <Blade t={t} at={v(25.85)} />
      {t > v(25.85) ? <End t={t} logo="logo-hd.png" ratio={899 / 1599} /> : null}
    </AbsoluteFill>
  );
};

import { loadFont as loadAnton } from "@remotion/google-fonts/Anton";
import { loadFont as loadMont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile } from "remotion";

// MENDES DELIVERY (cliente J. Vitor) — estética automotiva a domicílio em Blumenau.
// Identidade do Instagram: preto, dourado em degradê, título condensado pesado (Anton é o mais próximo).

export const { fontFamily: ANTON } = loadAnton("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });
export const { fontFamily: MONT } = loadMont("normal", { weights: ["600", "800"], subsets: ["latin", "latin-ext"] });

export const BG = "#080706";
export const GOLD = "#E9B949";
export const GOLD_HI = "#FFE29A";
export const GOLD_LO = "#B47F1C";
export const WHITE = "#FFFFFF";
export const GOLD_GRAD = `linear-gradient(180deg, ${GOLD_HI} 0%, ${GOLD} 48%, ${GOLD_LO} 100%)`;
export const asset = (f: string) => staticFile(`jvitor/${f}`);

export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
export const IN = Easing.bezier(0.55, 0, 0.9, 0.4);
// mola com pouco overshoot (≈4%)
export const SOFT = Easing.bezier(0.22, 1.25, 0.36, 1);
export const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
export const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: SOFT });
export const ein = (t: number, a: number, d = 0.35) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN });
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
export const mix = (a: number, b: number, p: number) => a + (b - a) * p;

// fundo liso com um calor dourado bem leve no centro
export const Back: React.FC<{ gold?: number }> = ({ gold = 1 }) => (
  <AbsoluteFill style={{ background: BG }}>
    <AbsoluteFill style={{ background: `radial-gradient(60% 40% at 50% 45%, rgba(233,185,73,${(0.1 * gold).toFixed(3)}) 0%, rgba(233,185,73,0) 70%)` }} />
    <AbsoluteFill style={{ background: "radial-gradient(95% 75% at 50% 50%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.55) 100%)" }} />
  </AbsoluteFill>
);

// texto que sobe da linha (máscara), palavra por palavra, e fica parado
type W = [string, number];
export const Line: React.FC<{
  t: number;
  words: W[];
  size: number;
  gold?: boolean;
  color?: string;
  out?: number;
  font?: string;
  spacing?: string;
}> = ({ t, words, size, gold, color = WHITE, out, font = ANTON, spacing = "0.01em" }) => {
  const o = out === undefined ? 0 : ein(t, out, 0.22);
  return (
    <div style={{ display: "flex", justifyContent: "center", gap: size * 0.24, whiteSpace: "nowrap", opacity: 1 - o, transform: `translateY(${(-o * size * 0.25).toFixed(1)}px)` }}>
      {words.map(([w, at], i) => {
        const e = k(t, at - 0.06, 0.42);
        return (
          <div key={i} style={{ overflow: "hidden", padding: `${size * 0.06}px ${size * 0.04}px ${size * 0.1}px` }}>
            <div
              style={{
                fontFamily: font,
                fontSize: size,
                lineHeight: 1.05,
                letterSpacing: spacing,
                textTransform: "uppercase",
                transform: `translateY(${((1 - e) * 135).toFixed(1)}%)`,
                ...(gold
                  ? { background: GOLD_GRAD, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent", filter: "drop-shadow(0 6px 0 rgba(0,0,0,0.5))" }
                  : { color, textShadow: "0 6px 0 rgba(0,0,0,0.45)" }),
              }}
            >
              {w}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ top, gap = 0, children, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap, ...style }}>{children}</div>
);

// traço que se desenha (ícones em linha dourada)
export const Draw: React.FC<{ d: string; p: number; w?: number; color?: string; len?: number }> = ({ d, p, w = 7, color = GOLD, len = 1600 }) => (
  <path d={d} fill="none" stroke={color} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={len} strokeDashoffset={len * (1 - p)} />
);

// relógio: o fio do vídeo (abre e volta na cena da rotina)
export const Clock: React.FC<{ t: number; p: number; speed: number; size?: number }> = ({ t, p, speed, size = 420 }) => {
  const a = speed;
  return (
    <svg width={size} height={size} viewBox="-120 -120 240 240" style={{ overflow: "visible" }}>
      <defs>
        <linearGradient id="jvg" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor={GOLD_HI} />
          <stop offset="0.5" stopColor={GOLD} />
          <stop offset="1" stopColor={GOLD_LO} />
        </linearGradient>
      </defs>
      <circle r={100} fill="none" stroke="url(#jvg)" strokeWidth={9} strokeDasharray={630} strokeDashoffset={630 * (1 - p)} transform="rotate(-90)" />
      {Array.from({ length: 12 }, (_, i) => (
        <line key={i} x1={0} y1={-84} x2={0} y2={i % 3 === 0 ? -70 : -76} stroke={GOLD} strokeWidth={i % 3 === 0 ? 7 : 4} strokeLinecap="round" transform={`rotate(${i * 30})`} opacity={lin(p, i / 14, i / 14 + 0.2)} />
      ))}
      <line x1={0} y1={0} x2={0} y2={-46} stroke={WHITE} strokeWidth={9} strokeLinecap="round" transform={`rotate(${(a / 12).toFixed(2)})`} opacity={p} />
      <line x1={0} y1={0} x2={0} y2={-68} stroke={GOLD_HI} strokeWidth={6} strokeLinecap="round" transform={`rotate(${a.toFixed(2)})`} opacity={p} />
      <circle r={9} fill={GOLD} opacity={p} />
    </svg>
  );
};

// lâmina dourada atravessando a tela (troca de cena)
export const Blade: React.FC<{ t: number; at: number; dir?: 1 | -1 }> = ({ t, at, dir = 1 }) => {
  if (t < at - 0.32 || t > at + 0.4) return null;
  return (
    <AbsoluteFill style={{ overflow: "hidden", zIndex: 30 }}>
      {[GOLD, "#000000"].map((c, i) => {
        const p = interpolate(t, [at - 0.3 + i * 0.07, at + 0.26 + i * 0.07], [0, 1], { ...cl, easing: IN_OUT });
        const x = dir === 1 ? -2400 + p * 4600 : 2400 - p * 4600;
        return <div key={i} style={{ position: "absolute", left: x - 300, top: -300, width: 1700, height: 2600, background: i === 0 ? GOLD_GRAD : c, transform: "skewX(-16deg)" }} />;
      })}
    </AbsoluteFill>
  );
};

// cartão de foto com borda dourada e aproximação lenta por dentro
export const Photo: React.FC<{ src: string; w: number; h: number; zoom: number; pos?: string; style?: React.CSSProperties }> = ({ src, w, h, zoom, pos = "50% 50%", style }) => (
  <div style={{ width: w, height: h, borderRadius: 30, overflow: "hidden", border: `5px solid ${GOLD}`, boxShadow: "0 40px 90px rgba(0,0,0,0.7), 0 0 40px rgba(233,185,73,0.18)", position: "relative", ...style }}>
    <Img src={src} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `scale(${zoom.toFixed(4)})` }} />
  </div>
);

import React from "react";
import { AbsoluteFill, Img, useCurrentFrame } from "remotion";
import { ANTON, asset, Back, Blade, BG, Clock, Col, Draw, GOLD, GOLD_GRAD, GOLD_HI, io, k, lin, Line, mix, MONT, Photo, pop, WHITE, ein } from "./comum";

// Mendes Delivery v1 — benefícios (não é promoção). Voz o locutor (src/voz-v1-cortada.wav, 34,13 s), entra em VO.
// Tempos abaixo = tempo da voz cortada (silencedetect), não o do arquivo original.

export const MD_FPS = 30;
const VO = 0.25;
export const MD_FRAMES = Math.round((34.13 + VO + 1.5) * MD_FPS);
const v = (s: number) => s + VO;

// troca de cena: cada cena vive entre [a, b] com uma folga para entrar e sair já em movimento
const live = (t: number, a: number, b: number) => t > a - 0.05 && t < b + 0.05;

