        <AbsoluteFill style={{ background: GOLD_GRAD, clipPath: `circle(${(flood * 160).toFixed(2)}% at 88% 62%)` }}>
          {t > v(8.2) ? <S4 t={t} /> : null}
        </AbsoluteFill>
      ) : null}
      {back > 0 ? (
        <AbsoluteFill style={{ clipPath: `circle(${(back * 120).toFixed(2)}% at 50% 50%)` }}>
          <Back />
          {live(t, v(10.5), v(14)) ? <S5 t={t} /> : null}
        </AbsoluteFill>
      ) : null}
      {live(t, v(13.6), v(21.2)) ? <S67 t={t} /> : null}
      {live(t, v(20.85), v(26)) ? <S8 t={t} /> : null}
      <Blade t={t} at={v(25.85)} />
      {t > v(25.85) ? <End t={t} /> : null}
    </AbsoluteFill>
  );
};

